HardwareSerial GNSS(1), GPSOut(2);
WebServer web(80); WiFiServer tcp(10110); WiFiClient clients[4];
GnssProductionPath gnssPath; SettingsManager settings; GnssLogger logger; EventEngine events; GeofenceEngine geofence;
GnssRecoveryLifecycle gnssRecovery(settings.get());
unsigned long packets=0, invalid=0, lastDataMs=0, lastWifiRetry=0; String wifiMode="AP";

bool protectedRoute(){ auto &c=settings.get(); if(!c.webAuthEnabled) return true; if(web.authenticate(c.webUsername.c_str(),c.webPassword.c_str())) return true; web.requestAuthentication(); return false; }
void sendJson(const JsonDocument&j){ String b; serializeJson(j,b); web.send(200,"application/json",b); }
void trackSummary(){ JsonDocument j; j["points"]=logger.size(); j["capacity"]=GnssLogger::MAX_POINTS; if(logger.size()){const auto&p=logger.at(0);const auto&l=logger.at(logger.size()-1);j["start_latitude"]=p.lat;j["start_longitude"]=p.lon;j["end_latitude"]=l.lat;j["end_longitude"]=l.lon;} sendJson(j); }
void trackExport(const String&format){ String body,type="text/plain",filename="track.txt"; if(format=="csv"){body=trackToCsv(logger);type="text/csv";filename="navic-track.csv";} else if(format=="gpx"){body=trackToGpx(logger);type="application/gpx+xml";filename="navic-track.gpx";} else if(format=="kml"){body=trackToKml(logger);type="application/vnd.google-earth.kml+xml";filename="navic-track.kml";} else {web.send(404,"application/json","{\"error\":\"unknown_export\"}");return;} web.sendHeader("Content-Disposition","attachment; filename="+filename); web.send(200,type,body); }

String apPassword(){ uint64_t mac=ESP.getEfuseMac(); char password[16]; snprintf(password,sizeof(password),"NavIC-%06llX",(unsigned long long)(mac & 0xFFFFFFULL)); return String(password); }
String apSsid(){ uint64_t mac=ESP.getEfuseMac(); char ssid[32]; snprintf(ssid,sizeof(ssid),"NavIC-GPS-%04llX",(unsigned long long)(mac & 0xFFFFULL)); return String(ssid); }

String page(){
  String html=R"HTML(<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>NavIC GPS Bridge</title><style>body{margin:0;font:15px system-ui;background:#08111f;color:#eaf2ff}.top{padding:16px;background:#0d1930}.wrap{max-width:820px;margin:auto;padding:16px}.card{background:#12223e;border:1px solid #28456f;border-radius:14px;padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.label{font-size:11px;color:#9bb0da;text-transform:uppercase}.value{font-size:22px;font-weight:700;margin-top:5px}input,select,button{width:100%;box-sizing:border-box;padding:10px;margin:6px 0;border-radius:8px;border:1px solid #38547d;background:#09172b;color:#fff}button{cursor:pointer;background:#1c5f9e}.row{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}small{color:#9bb0da}.ok{color:#62e6a3}.bad{color:#ff7891}</style></head><body><div class=top><b>🛰 NavIC GPS Bridge</b></div><main class=wrap><div class=grid><div class=card><div class=label>Fix</div><div id=fix class=value>—</div></div><div class=card><div class=label>Position</div><div id=pos class=value>—</div></div><div class=card><div class=label>Satellites</div><div id=sat class=value>—</div></div><div class=card><div class=label>Speed</div><div id=speed class=value>—</div></div></div><div class=card><b>Configuration</b><input id=ssid placeholder="Wi-Fi SSID"><input id=stap type=password placeholder="Wi-Fi password (leave blank to keep)"><input id=gb type=number placeholder="GNSS baud"><input id=ob type=number placeholder="Output baud"><input id=port type=number placeholder="TCP port"><select id=profile><option value=generic>Generic GPS</option><option value=legacy>Legacy GPS</option><option value=marine>Marine</option><option value=automotive>Automotive</option><option value=flight>Flight Controller</option></select><label><input id=ap type=checkbox> Keep device AP enabled</label><label><input id=sta type=checkbox> Join configured Wi-Fi</label><label><input id=compat type=checkbox> GPS compatibility conversion</label><div class=grid><input id=rs type=number placeholder="Recovery silence (ms)"><input id=rc type=number placeholder="Recovery cooldown (ms)"></div><button onclick=save()>Save configuration</button><small id=cfg></small></div><div class=card><b>Web authentication</b><label><input id=auth type=checkbox> Require username/password for web and OTA</label><input id=authuser placeholder="Username"><input id=authpass type=password placeholder="New password (12–64 characters)"><button onclick=saveAuth()>Save authentication</button><small id=authmsg></small></div><div class=card><b>Geofence</b><label><input id=geo type=checkbox> Enable circular geofence</label><input id=glat type=number step=any placeholder="Latitude"><input id=glon type=number step=any placeholder="Longitude"><input id=gradius type=number step=1 placeholder="Radius (metres)"><button onclick=saveGeo()>Save geofence</button></div><div class=card><b>Track export</b><small id=track>Loading…</small><div class=row><button onclick="location='/api/track/csv'">CSV</button><button onclick="location='/api/track/gpx'">GPX</button><button onclick="location='/api/track/kml'">KML</button></div></div>)HTML";
  html += eventDashboardHtml();
  html += R"HTML(<div class=card><b>Maintenance</b><button onclick=post('/api/restart')>Restart device</button><button onclick=post('/api/reset')>Factory reset</button><button onclick=post('/api/track/clear')>Clear track</button><button onclick=ota()>OTA firmware update</button><input id=bin type=file accept=.bin style="display:none" onchange=upload()><small id=maint></small></div></main><script>async function load(){let d=await(await fetch('/api/live',{cache:'no-store'})).json();fix.textContent=d.fix?'VALID FIX':'NO FIX';fix.className='value '+(d.fix?'ok':'bad');pos.textContent=d.latitude.toFixed(6)+', '+d.longitude.toFixed(6);sat.textContent=d.satellites;speed.textContent=d.speed_kmh.toFixed(1)+' km/h'}async function config(){let c=await(await fetch('/api/config')).json();ssid.value=c.sta_ssid;gb.value=c.gnss_baud;ob.value=c.gps_out_baud;port.value=c.tcp_port;profile.value=c.output_profile||'generic';ap.checked=c.ap_enabled;sta.checked=c.sta_enabled;compat.checked=c.gps_compatibility;rs.value=c.gnss_recovery_silence_ms;rc.value=c.gnss_recovery_cooldown_ms;geo.checked=c.geofence_enabled;glat.value=c.geofence_latitude;glon.value=c.geofence_longitude;gradius.value=c.geofence_radius_m;auth.checked=c.web_auth_enabled;authuser.value=c.web_username||''}async function loadTrack(){let t=await(await fetch('/api/track')).json();track.textContent=t.points+' point(s) retained, capacity '+t.capacity}async function save(){let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sta_ssid:ssid.value,sta_password:stap.value,gnss_baud:+gb.value,gps_out_baud:+ob.value,tcp_port:+port.value,output_profile:profile.value,ap_enabled:ap.checked,sta_enabled:sta.checked,gps_compatibility:compat.checked,gnss_recovery_silence_ms:+rs.value,gnss_recovery_cooldown_ms:+rc.value})});let d=await r.json();cfg.textContent=d.ok?'Saved. Recovery policy applies immediately; other serial/network changes require restart.':d.error}async function saveAuth(){let r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:auth.checked,username:authuser.value,password:authpass.value})});let d=await r.json();authmsg.textContent=d.ok?(d.reauth_required?'Authentication changed. The browser may prompt for the new credentials on the next request.':'Authentication disabled.'):(d.error||'Authentication update failed');if(d.ok)authpass.value=''}async function saveGeo(){let r=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({geofence_enabled:geo.checked,geofence_latitude:+glat.value,geofence_longitude:+glon.value,geofence_radius_m:+gradius.value})});let d=await r.json();cfg.textContent=d.ok?'Geofence saved.':d.error}async function post(u){let r=await fetch(u,{method:'POST'});maint.textContent=await r.text();loadTrack()}function ota(){bin.click()}async function upload(){if(!bin.files[0])return;let f=new FormData();f.append('update',bin.files[0]);let r=await fetch('/api/ota',{method:'POST',body:f});maint.textContent=await r.text()}load();config();loadTrack();loadEvents();setInterval(load,1000);setInterval(loadEvents,5000)</script></body></html>)HTML";
  return html;
}

void live(){ LiveDiagnosticsCounters c; c.packets=packets;c.invalidPackets=invalid;c.lastDataMs=lastDataMs;c.wifiMode=wifiMode.c_str();c.geofenceInside=geofence.inside();c.geofenceEvents=geofence.eventCount();c.geofenceLastEventMs=geofence.lastEventAt();GnssHealth snapshot;attachGnssRuntimeDiagnostics(c,gnssPath.runtime(),millis(),snapshot);gnssRecovery.attachDiagnostics(c);JsonDocument j;buildLiveDiagnostics(gnssPath.data(),events,c,millis(),j);sendJson(j); }
void configGet(){ auto&c=settings.get(); JsonDocument j; j["gnss_baud"]=c.gnssBaud;j["gps_out_baud"]=c.gpsOutBaud;j["tcp_port"]=c.tcpPort;j["gps_compatibility"]=c.gpsCompatibility;j["ap_enabled"]=c.apEnabled;j["sta_enabled"]=c.staEnabled;j["sta_ssid"]=c.staSsid;j["web_auth_enabled"]=c.webAuthEnabled;j["web_username"]=c.webUsername;j["web_password_configured"]=c.webPassword.length() >= WebAuthPolicy::MIN_PASSWORD_LENGTH;j["output_profile"]=c.outputProfile;j["geofence_enabled"]=c.geofenceEnabled;j["geofence_latitude"]=c.geofenceLatitude;j["geofence_longitude"]=c.geofenceLongitude;j["geofence_radius_m"]=c.geofenceRadiusM;GnssRecoveryConfig::addToJson(c,j);sendJson(j); }
void configPost(){ JsonDocument j;if(deserializeJson(j,web.arg("plain"))){web.send(400,"application/json","{\"ok\":false,\"error\":\"invalid_json\"}");return;}BridgeConfig c=settings.get();if(j["gnss_baud"].is<uint32_t>())c.gnssBaud=j["gnss_baud"];if(j["gps_out_baud"].is<uint32_t>())c.gpsOutBaud=j["gps_out_baud"];if(j["tcp_port"].is<uint16_t>())c.tcpPort=j["tcp_port"];if(j["gps_compatibility"].is<bool>())c.gpsCompatibility=j["gps_compatibility"];if(j["ap_enabled"].is<bool>())c.apEnabled=j["ap_enabled"];if(j["sta_enabled"].is<bool>())c.staEnabled=j["sta_enabled"];if(j["sta_ssid"].is<String>())c.staSsid=j["sta_ssid"].as<String>();if(j["sta_password"].is<String>()&&j["sta_password"].as<String>().length())c.staPassword=j["sta_password"].as<String>();if(j["output_profile"].is<String>()){String p=j["output_profile"].as<String>();BridgeConfig prof=c;if(!ConfigProfiles::apply(p,prof)){web.send(422,"application/json","{\"ok\":false,\"error\":\"invalid_profile\"}");return;}c.gpsOutBaud=prof.gpsOutBaud;c.gpsCompatibility=prof.gpsCompatibility;c.outputProfile=p;}if(j["geofence_enabled"].is<bool>())c.geofenceEnabled=j["geofence_enabled"];if(j["geofence_latitude"].is<double>())c.geofenceLatitude=j["geofence_latitude"];if(j["geofence_longitude"].is<double>())c.geofenceLongitude=j["geofence_longitude"];if(j["geofence_radius_m"].is<float>())c.geofenceRadiusM=j["geofence_radius_m"];GnssRecoveryConfig::applyFromJson(j,c);const bool coordinatesValid=isfinite(c.geofenceLatitude)&&isfinite(c.geofenceLongitude)&&c.geofenceLatitude>=-90.0&&c.geofenceLatitude<=90.0&&c.geofenceLongitude>=-180.0&&c.geofenceLongitude<=180.0;const bool radiusValid=isfinite(c.geofenceRadiusM)&&c.geofenceRadiusM>=1.0f&&c.geofenceRadiusM<=100000.0f;if(c.gnssBaud<1200||c.gnssBaud>921600||c.gpsOutBaud<1200||c.gpsOutBaud>921600||c.tcpPort<1024||!coordinatesValid||!radiusValid){web.send(422,"application/json","{\"ok\":false,\"error\":\"invalid_settings\"}");return;}settings.save(c);gnssRecovery.reconfigure(c);Geofence fence;fence.enabled=c.geofenceEnabled;fence.latitude=c.geofenceLatitude;fence.longitude=c.geofenceLongitude;fence.radiusMeters=c.geofenceRadiusM;geofence.set(fence);web.send(200,"application/json","{\"ok\":true,\"restart_required\":true,\"recovery_policy_applied\":true}");}
void authPost(){ JsonDocument j;if(deserializeJson(j,web.arg("plain"))){web.send(400,"application/json","{\"ok\":false,\"error\":\"invalid_json\"}");return;}BridgeConfig c=settings.get();const bool enabled=j["enabled"].is<bool>()?j["enabled"].as<bool>():c.webAuthEnabled;String username=j["username"].is<String>()?j["username"].as<String>():c.webUsername;String password=j["password"].is<String>()?j["password"].as<String>():String();if(!WebAuthPolicy::validUsername(username)){web.send(422,"application/json","{\"ok\":false,\"error\":\"invalid_username\"}");return;}if(enabled){if(password.length()==0)password=c.webPassword;if(!WebAuthPolicy::validPassword(password)){web.send(422,"application/json","{\"ok\":false,\"error\":\"password_must_be_12_to_64_characters\"}");return;}c.webPassword=password;}else if(password.length()>0&&!WebAuthPolicy::validPassword(password)){web.send(422,"application/json","{\"ok\":false,\"error\":\"password_must_be_12_to_64_characters\"}");return;}c.webUsername=username;c.webAuthEnabled=enabled;settings.save(c);JsonDocument r;r["ok"]=true;r["web_auth_enabled"]=enabled;r["reauth_required"]=enabled||c.webAuthEnabled;r["password_configured"]=c.webPassword.length()>=WebAuthPolicy::MIN_PASSWORD_LENGTH;sendJson(r);}
void setupWifi(){auto&c=settings.get();bool ap=c.apEnabled;if(c.staEnabled&&c.staSsid.length()){WiFi.mode(ap?WIFI_AP_STA:WIFI_STA);WiFi.begin(c.staSsid.c_str(),c.staPassword.c_str());unsigned long start=millis();while(WiFi.status()!=WL_CONNECTED&&millis()-start<10000){delay(100);esp_task_wdt_reset();}wifiMode=WiFi.status()==WL_CONNECTED?(ap?"AP+STA":"STA"):(ap?"AP":"OFFLINE");}else{WiFi.mode(ap?WIFI_AP:WIFI_OFF);wifiMode=ap?"AP":"OFFLINE";}if(ap){String ssid=apSsid();String password=apPassword();WiFi.softAP(ssid.c_str(),password.c_str());Serial.printf("NavIC-GPS AP: %s / password: %s\n",ssid.c_str(),password.c_str());}}
void restartDevice(){web.send(200,"application/json","{\"ok\":true}");delay(300);ESP.restart();}void resetDevice(){settings.reset();web.send(200,"application/json","{\"ok\":true,\"restart_required\":true}");delay(300);ESP.restart();}
void setup(){Serial.begin(115200);esp_task_wdt_init(15,true);esp_task_wdt_add(NULL);settings.begin();auto&c=settings.get();gnssRecovery.reconfigure(c);GNSS.begin(c.gnssBaud,SERIAL_8N1,16,17);GPSOut.begin(c.gpsOutBaud,SERIAL_8N1,-1,18);gnssRecovery.begin(millis());Geofence fence;fence.enabled=c.geofenceEnabled;fence.latitude=c.geofenceLatitude;fence.longitude=c.geofenceLongitude;fence.radiusMeters=c.geofenceRadiusM;geofence.set(fence);setupWifi();tcp.begin(c.tcpPort);web.on("/",[]{if(protectedRoute())web.send(200,"text/html",page());});web.on("/api/live",[]{if(protectedRoute())live();});registerEventRoutes(web,events,protectedRoute);web.on("/api/config",HTTP_GET,[]{if(protectedRoute())configGet();});web.on("/api/config",HTTP_POST,[]{if(protectedRoute())configPost();});web.on("/api/auth",HTTP_POST,[]{if(protectedRoute())authPost();});web.on("/api/track",HTTP_GET,[]{if(protectedRoute())trackSummary();});web.on("/api/track/csv",HTTP_GET,[]{if(protectedRoute())trackExport("csv");});web.on("/api/track/gpx",HTTP_GET,[]{if(protectedRoute())trackExport("gpx");});web.on("/api/track/kml",HTTP_GET,[]{if(protectedRoute())trackExport("kml");});web.on("/api/restart",HTTP_POST,[]{if(protectedRoute())restartDevice();});web.on("/api/reset",HTTP_POST,[]{if(protectedRoute())resetDevice();});web.on("/api/track/clear",HTTP_POST,[]{if(protectedRoute()){logger.clear();web.send(200,"application/json","{\"ok\":true}");}});web.on("/api/ota",HTTP_POST,[]{if(!protectedRoute())return;web.send(200,"text/plain",Update.hasError()?"OTA failed":"OTA successful. Restarting…");delay(300);if(!Update.hasError())ESP.restart();},[]{if(!protectedRoute())return;HTTPUpload&u=web.upload();if(u.status==UPLOAD_FILE_START)Update.begin(UPDATE_SIZE_UNKNOWN);else if(u.status==UPLOAD_FILE_WRITE){if(Update.write(u.buf,u.currentSize)!=u.currentSize)Update.abort();}else if(u.status==UPLOAD_FILE_END)Update.end(true);});web.begin();}
void loop(){esp_task_wdt_reset();web.handleClient();if(settings.get().staEnabled&&WiFi.status()!=WL_CONNECTED&&millis()-lastWifiRetry>30000&&settings.get().staSsid.length()){lastWifiRetry=millis();WiFi.disconnect();WiFi.begin(settings.get().staSsid.c_str(),settings.get().staPassword.c_str());}WiFiClient incoming=tcp.available();if(incoming){bool acceptedClient=false;for(auto&c:clients)if(!c||!c.connected()){c=incoming;acceptedClient=true;break;}if(!acceptedClient)incoming.stop();}while(GNSS.available()){String l=GNSS.readStringUntil('\n');l.trim();if(!l.length())continue;String o;bool accepted=gnssPath.process(l,millis(),settings.get().gpsCompatibility,o);gnssRecovery.observeAccepted(accepted,millis());if(!accepted){invalid++;continue;}packets++;lastDataMs=millis();auto&d=gnssPath.data();logger.add(d.latitude,d.longitude,d.altitude,d.speedKmh,millis());events.update(d,true,millis());if(settings.get().geofenceEnabled)geofence.update(d.latitude,d.longitude,d.fix,millis());GPSOut.println(o);for(auto&c:clients)if(c&&c.connected())c.println(o);}gnssRecovery.poll(millis(),GNSS,settings.get());events.update(gnssPath.data(),millis()-lastDataMs<3000,millis());}
